export { Orbling, type OrblingProps } from "./orbling";
export { OrblingStatus } from "./status";
export { MOODS, MOOD_NAMES, PALETTES, type Mood, type Palette } from "./moods";

import { useRef, type CSSProperties } from "react";
import { Ball } from "./ball";
import { Effects } from "./effects";
import type { Mood, Palette } from "./moods";
import { useAct } from "./use-act";
import { useGaze } from "./use-gaze";
import "./orbling.css";

export type OrblingProps = {
  mood?: Mood;
  size?: number;
  palette?: Palette;
  hue?: number;
  heat?: boolean;
  label?: string;
  className?: string;
};

export function Orbling({
  mood = "idle",
  size = 72,
  palette = "sky",
  hue = 0,
  heat = true,
  label,
  className = "",
}: OrblingProps) {
  const root = useRef<HTMLSpanElement>(null);
  const [act, advance] = useAct(mood);
  const style = { fontSize: size, "--hue": `${hue}deg` } as CSSProperties;

  useGaze(root, act === "watch");

  return (
    <span
      ref={root}
      className={`orbling ${className}`.trim()}
      data-act={act}
      data-palette={palette}
      style={style}
      role={label ? "img" : undefined}
      aria-label={label}
      aria-hidden={!label}
    >
      <span key={act} className="orbling-clock" onAnimationIteration={advance} />
      <Effects />
      <span className="orbling-body">
        <span className="orbling-mask">
          <Ball size={size} heat={heat} palette={palette} />
          <span className="orbling-shade" />
        </span>
        <span className="orbling-tint" />
      </span>
    </span>
  );
}

import { MOODS } from "./moods";
import { Orbling, type OrblingProps } from "./orbling";

export function OrblingStatus({ mood = "idle", label, size = 16, heat = false, className = "", ...orb }: OrblingProps) {
  return (
    <span className={`orbling-status ${className}`.trim()} role="status">
      <Orbling {...orb} mood={mood} size={size} heat={heat} />
      <span className="orbling-label">{label ?? MOODS[mood].label}</span>
    </span>
  );
}

import { useState } from "react";
import { MOODS, type Act, type Mood } from "./moods";

function actAt(mood: Mood, step: number): Act {
  const { intro, loop } = MOODS[mood];
  if (intro && step === 0) return intro;
  return loop[(intro ? step - 1 : step) % loop.length];
}

export function useAct(mood: Mood) {
  const [play, setPlay] = useState({ mood, step: 0 });

  if (play.mood !== mood) setPlay({ mood, step: 0 });

  function advance() {
    setPlay((current) => ({ ...current, step: current.step + 1 }));
  }

  return [actAt(mood, play.step), advance] as const;
}

import { useEffect, type RefObject } from "react";

const EASE = 0.3;

function clamp(value: number) {
  return Math.max(-1, Math.min(1, value));
}

function follow(root: HTMLElement) {
  const eyes = root.querySelector<HTMLElement>(".orbling-eyes")!;
  const body = root.querySelector<HTMLElement>(".orbling-body")!;
  const aim = { x: 0, y: 0 };
  const look = { x: 0, y: 0 };
  let center = { x: 0, y: 0, reach: 0 };
  let frame = 0;

  function measure() {
    const box = root.getBoundingClientRect();
    center = { x: box.left + box.width / 2, y: box.top + box.height / 2, reach: Math.max(box.width * 4, 240) };
  }

  function draw() {
    look.x += (aim.x - look.x) * EASE;
    look.y += (aim.y - look.y) * EASE;
    eyes.style.setProperty("--ry", `${look.x * 28}deg`);
    eyes.style.setProperty("--rx", `${look.y * -24}deg`);
    body.style.rotate = `${look.x * 6}deg`;
    body.style.translate = `${look.x * 0.02}em ${look.y * 0.015}em`;
    const moving = Math.abs(aim.x - look.x) + Math.abs(aim.y - look.y) > 0.002;
    frame = moving ? requestAnimationFrame(draw) : 0;
  }

  function aimAt(event: PointerEvent) {
    aim.x = clamp((event.clientX - center.x) / center.reach);
    aim.y = clamp((event.clientY - center.y) / center.reach);
    if (!frame) frame = requestAnimationFrame(draw);
  }

  measure();
  window.addEventListener("pointermove", aimAt, { passive: true });
  window.addEventListener("scroll", measure, { passive: true });
  window.addEventListener("resize", measure);

  return () => {
    window.removeEventListener("pointermove", aimAt);
    window.removeEventListener("scroll", measure);
    window.removeEventListener("resize", measure);
    cancelAnimationFrame(frame);
    eyes.style.removeProperty("--ry");
    eyes.style.removeProperty("--rx");
    body.style.removeProperty("rotate");
    body.style.removeProperty("translate");
  };
}

export function useGaze(ref: RefObject<HTMLElement | null>, active: boolean) {
  useEffect(() => {
    if (active && ref.current) return follow(ref.current);
  }, [ref, active]);
}

import { Heat } from "./heat";
import type { Palette } from "./moods";

export function Ball({ size, heat, palette }: { size: number; heat: boolean; palette: Palette }) {
  return (
    <span className="orbling-ball">
      {heat ? <Heat size={size} palette={palette} /> : <span className="orbling-heat" />}
      <span className="orbling-gloss" />
      <span className="orbling-eyes">
        <i />
        <i />
      </span>
    </span>
  );
}

import { Suspense, useState } from "react";
import { Heatmap } from "@paper-design/shaders-react";
import type { Palette } from "./moods";

const CIRCLE =
  "data:image/svg+xml," +
  encodeURIComponent(
    '<svg xmlns="http://www.w3.org/2000/svg" width="400" height="400"><circle cx="200" cy="200" r="150" fill="#000"/></svg>',
  );

const COLORS: Record<Palette, string[]> = {
  sky: ["#c0e4fc", "#a9c8fd", "#7ea8f8", "#7a9eeb"],
  mono: ["#ececee", "#d6d6da", "#b9b9c0", "#a6a6ad"],
  night: ["#c4e4ff", "#9ccaff", "#6aa6f6", "#4a86e4"],
};

const FILL = { position: "absolute", inset: 0, width: "100%", height: "100%" } as const;

function now() {
  return typeof performance === "undefined" ? 0 : performance.now();
}

export function Heat({ size, palette }: { size: number; palette: Palette }) {
  const [frame] = useState(now);

  return (
    <Suspense fallback={<span className="orbling-heat" />}>
      <Heatmap
        suspendWhenProcessingImage
        maxPixelCount={(size * 2) ** 2}
        style={FILL}
        image={CIRCLE}
        colorBack="#00000000"
        colors={COLORS[palette]}
        contour={0.6}
        innerGlow={0.5}
        outerGlow={1}
        noise={0.2}
        scale={1.3}
        speed={0.3}
        frame={frame}
      />
    </Suspense>
  );
}

import { useId, type CSSProperties } from "react";

const ZS = [0, 1, 2];

function QuestionMark() {
  const gradient = useId();

  return (
    <svg className="orbling-q" viewBox="0 0 100 140">
      <defs>
        <linearGradient id={gradient} x1="0" y1="0" x2="0" y2="1">
          <stop offset="0" stopColor="var(--blue)" />
          <stop offset="1" stopColor="var(--blue-deep)" />
        </linearGradient>
      </defs>
      <path
        className="orbling-q-hook"
        pathLength={1}
        stroke={`url(#${gradient})`}
        d="M24 40 C24 18 40 6 58 6 C78 6 92 20 92 38 C92 56 78 64 68 72 C61 78 58 84 58 96"
      />
      <circle className="orbling-q-dot" cx="58" cy="122" r="10" />
    </svg>
  );
}

function Bang() {
  return (
    <svg className="orbling-bang" viewBox="0 0 40 100">
      <path d="M20 4 C27 4 31 9 30 16 L26 62 C25.5 67 23 69 20 69 C17 69 14.5 67 14 62 L10 16 C9 9 13 4 20 4 Z" />
      <circle cx="20" cy="87" r="9" />
    </svg>
  );
}

export function Effects() {
  return (
    <span className="orbling-fx">
      <span className="orbling-dot" data-side="l" />
      <span className="orbling-dot" data-side="r" />
      {ZS.map((i) => (
        <span key={i} className="orbling-z" style={{ "--i": i } as CSSProperties}>
          z
        </span>
      ))}
      <QuestionMark />
      <Bang />
    </span>
  );
}

@property --ry {
  syntax: "<angle>";
  inherits: false;
  initial-value: 0deg;
}

@property --rx {
  syntax: "<angle>";
  inherits: false;
  initial-value: 0deg;
}

.orbling {
  --ball: #c0e4fc;
  --ground-light: #d6eefd;
  --ground-dark: #93b9f3;
  --eye: #194094;
  --blue: #7ea8f8;
  --blue-deep: #3574fd;
  --heat: #7a9eeb;
  --heat-pale: #a9c8fd;
  --underside: hsl(215 45% 62% / 0.35);
  --shade-light: #9ab5ec;
  --shade-dark: #7d9de2;
  --gloss: 0.75;
  --halo: color-mix(in srgb, var(--blue) 60%, transparent);
  --halo-blur: 0.045em;
  --ease: cubic-bezier(0.45, 0, 0.25, 1);
  --in: cubic-bezier(0.16, 1, 0.3, 1);
  --out: cubic-bezier(0.7, 0, 0.84, 0);
  --whip: cubic-bezier(0.6, 0, 0.2, 1);
  --rise: cubic-bezier(0.2, 0.6, 0.35, 1);
  --fall: cubic-bezier(0.6, 0, 0.8, 0.4);
  --disc: radial-gradient(circle closest-side, #000 calc(100% - 1px), transparent 100%);
  --gear: url("data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%20100%20100%27%3E%3Cpath%20d%3D%27M39.23%2015.65%20L41.41%202.27%20L58.59%202.27%20L60.77%2015.65%20A36%2036%200%200%201%2074.37%2023.50%20L87.04%2018.70%20L95.63%2033.57%20L85.13%2042.15%20A36%2036%200%200%201%2085.13%2057.85%20L95.63%2066.43%20L87.04%2081.30%20L74.37%2076.50%20A36%2036%200%200%201%2060.77%2084.35%20L58.59%2097.73%20L41.41%2097.73%20L39.23%2084.35%20A36%2036%200%200%201%2025.63%2076.50%20L12.96%2081.30%20L4.37%2066.43%20L14.87%2057.85%20A36%2036%200%200%201%2014.87%2042.15%20L4.37%2033.57%20L12.96%2018.70%20L25.63%2023.50%20A36%2036%200%200%201%2039.23%2015.65%20Z%27%20fill%3D%27black%27%20stroke%3D%27black%27%20stroke-width%3D%273%27%20stroke-linejoin%3D%27round%27%2F%3E%3C%2Fsvg%3E");
  --d: 4s;
  position: relative;
  display: inline-block;
  flex-shrink: 0;
  width: 1em;
  height: 1em;
  line-height: 1;
  vertical-align: middle;
  filter: hue-rotate(var(--hue, 0deg));
}

.orbling[data-palette="mono"] {
  --ball: #e7e7ea;
  --ground-light: #f4f4f5;
  --ground-dark: #b9b9c0;
  --eye: #27272a;
  --blue: #a1a1aa;
  --blue-deep: #52525b;
  --heat: #a8a8b0;
  --heat-pale: #d4d4d8;
  --underside: hsl(240 5% 45% / 0.3);
  --shade-light: #c4c4cc;
  --shade-dark: #9d9da6;
}

.orbling[data-palette="night"] {
  --ball: #c4e4ff;
  --ground-light: #e8f6ff;
  --ground-dark: #7fb0ee;
  --eye: #0b1d42;
  --blue: #9ccdff;
  --blue-deep: #69a6f7;
  --heat: #5f9bf0;
  --heat-pale: #a8d2ff;
  --underside: hsl(210 60% 42% / 0.38);
  --shade-light: #8bbcf0;
  --shade-dark: #5f95dc;
  --gloss: 0.6;
}

.orbling-clock {
  position: absolute;
  width: 0;
  height: 0;
  animation: orbling-clock var(--d) linear infinite;
}

.orbling-body {
  position: absolute;
  inset: 0;
  z-index: 1;
}

.orbling-mask {
  position: absolute;
  inset: -12.5%;
  mask-repeat: no-repeat;
  mask-position: center;
}

.orbling-ball {
  position: absolute;
  inset: 10%;
  overflow: hidden;
  isolation: isolate;
  border-radius: 50%;
  container-type: size;
  background: radial-gradient(circle at 34% 28%, var(--ground-light), var(--ball) 45%, var(--ground-dark) 100%);
  box-shadow: 0 0 var(--halo-blur) 0.0075em var(--halo);
  animation: orbling-breathe 5s ease-in-out infinite;
}

.orbling-gloss,
.orbling-heat,
.orbling-eyes {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.orbling-gloss {
  border-radius: inherit;
  background: radial-gradient(
    circle at 32% 22%,
    rgb(255 255 255 / var(--gloss)),
    rgb(255 255 255 / calc(var(--gloss) * 0.16)) 30%,
    transparent 46%
  );
  box-shadow:
    inset 0 -8cqw 16cqw var(--underside),
    inset 0 2cqw 4cqw rgb(255 255 255 / 0.45),
    inset 0 0 0 1px rgb(255 255 255 / 0.25);
}

.orbling-heat {
  border-radius: inherit;
  overflow: hidden;
}

.orbling-heat::before,
.orbling-heat::after {
  content: "";
  position: absolute;
  inset: 10%;
  border-radius: 50%;
  opacity: 0;
  filter: blur(9cqw);
  background: radial-gradient(circle, var(--heat) 0%, var(--blue) 35%, transparent 70%);
  animation: orbling-heat-a 7.5s ease-in-out infinite;
}

.orbling-heat::after {
  inset: 20%;
  background: radial-gradient(circle, var(--blue) 0%, var(--heat-pale) 40%, transparent 72%);
  animation: orbling-heat-b 9.7s ease-in-out infinite;
}

.orbling-eyes {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 14cqw;
  padding-bottom: 4cqw;
  backface-visibility: hidden;
  transform: perspective(260cqw) translateZ(-50cqw) rotateY(var(--ry)) rotateX(var(--rx)) translateZ(50cqw);
}

.orbling-eyes i {
  position: relative;
  width: 10cqw;
  height: 19cqw;
  border-radius: 9999px;
  background-color: var(--eye);
  animation: orbling-blink 6.3s ease-in-out infinite;
}

.orbling-shade {
  position: absolute;
  inset: 10%;
  z-index: 3;
  border-radius: 50%;
  opacity: 0;
  pointer-events: none;
  mix-blend-mode: multiply;
  background: radial-gradient(circle, var(--shade-light), var(--shade-dark));
}

.orbling-tint {
  position: absolute;
  inset: 0;
  z-index: 2;
  border-radius: 50%;
  opacity: 0;
  background: linear-gradient(180deg, var(--blue), var(--blue-deep));
}

.orbling-fx {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.orbling-fx > * {
  position: absolute;
  opacity: 0;
  overflow: visible;
}

.orbling-dot {
  inset: 0;
  z-index: 2;
  margin: auto;
  width: 22%;
  height: 22%;
  border-radius: 50%;
  background: linear-gradient(180deg, var(--blue), var(--blue-deep));
}

.orbling-z {
  --z: 0.42;
  --zs: calc(0.8 + var(--i) * 0.22);
  z-index: 2;
  font: 800 calc(var(--z) * 1em) / 1 ui-rounded, "SF Pro Rounded", system-ui, sans-serif;
  left: calc((0.68em + var(--i) * 0.06em) / var(--z));
  top: calc(-0.02em / var(--z));
  color: var(--blue-deep);
}

.orbling-q {
  z-index: 2;
}

.orbling-q-hook {
  fill: none;
  stroke-width: 16;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-dasharray: 1;
  stroke-dashoffset: 1;
}

.orbling-q-dot {
  fill: var(--blue-deep);
  opacity: 0;
  transform-box: fill-box;
  transform-origin: center;
}

.orbling-bang {
  z-index: 2;
  left: 0.86em;
  top: -0.36em;
  width: 0.17em;
  height: 0.42em;
  fill: var(--blue-deep);
  transform-origin: 50% 100%;
}

.orbling-status {
  display: inline-flex;
  align-items: center;
  gap: 0.5em;
}

.orbling-label {
  mask-image: linear-gradient(90deg, #000 40%, rgb(0 0 0 / 0.35) 50%, #000 60%);
  mask-size: 300% 100%;
  animation: orbling-shimmer 2.4s linear infinite;
}

@keyframes orbling-shimmer {
  from {
    mask-position: 100% 0;
  }
  to {
    mask-position: 0 0;
  }
}

@keyframes orbling-clock {
  to {
    opacity: 1;
  }
}

@keyframes orbling-breathe {
  0%, 100% { scale: 1; }
  50% { scale: 1.035; }
}

@keyframes orbling-blink {
  0%, 44%, 48%, 90%, 93%, 96%, 100% { scale: 1 1; }
  46%, 91.5%, 94.5% { scale: 1 0.1; }
}

@keyframes orbling-heat-a {
  0%, 100% { translate: -30% 25%; opacity: 0.4; }
  20% { opacity: 0.95; }
  50% { translate: 20% -20%; opacity: 0.8; }
  75% { opacity: 0.45; }
}

@keyframes orbling-heat-b {
  0%, 100% { translate: 35% 30%; opacity: 0.35; }
  30% { opacity: 0.85; }
  60% { translate: -25% -15%; opacity: 0.7; }
  85% { opacity: 0.4; }
}

@keyframes orbling-eyes-out {
  0%, 6% { opacity: 1; }
  18%, 82% { opacity: 0; }
  94%, 100% { opacity: 1; }
}

.orbling[data-act="idle"] { --d: 11s; }
.orbling[data-act="spin"] { --d: 1.5s; }
.orbling[data-act="dots"] { --d: 3.8s; }
.orbling[data-act="gear"] { --d: 3.8s; }
.orbling[data-act="ponder"] { --d: 4.6s; }
.orbling[data-act="read"] { --d: 4.2s; }
.orbling[data-act="wonder"] { --d: 4.2s; }
.orbling[data-act="down"] { --d: 4.2s; }
.orbling[data-act="stamp"] { --d: 4.2s; }
.orbling[data-act="surprise"] { --d: 2.6s; }
.orbling[data-act="sleep"] { --d: 5.6s; }
.orbling[data-act="shake"] { --d: 2.4s; }
.orbling[data-act="watch"] { --d: 4s; }

.orbling[data-act="idle"] .orbling-eyes {
  animation: orbling-look-around var(--d) cubic-bezier(0.45, 0, 0.2, 1) infinite;
}

@keyframes orbling-look-around {
  0%, 16% { --ry: 0deg; --rx: 0deg; }
  20%, 34% { --ry: -20deg; --rx: 5deg; }
  38%, 50% { --ry: 0deg; --rx: 0deg; }
  54%, 66% { --ry: 18deg; --rx: -3deg; }
  70%, 80% { --ry: 5deg; --rx: 14deg; }
  84%, 100% { --ry: 0deg; --rx: 0deg; }
}

.orbling[data-act="spin"] .orbling-eyes {
  animation: orbling-spin-eyes var(--d) var(--whip) infinite both;
}

.orbling[data-act="spin"] .orbling-body {
  animation: orbling-spin-body var(--d) var(--whip) infinite both;
}

@keyframes orbling-spin-eyes {
  0% { --ry: 0deg; animation-timing-function: cubic-bezier(0.25, 0.6, 0.35, 1); }
  18% { --ry: -24deg; animation-timing-function: cubic-bezier(0.85, 0, 0.15, 1); }
  56% { --ry: 376deg; animation-timing-function: cubic-bezier(0.45, 0, 0.55, 1); }
  70% { --ry: 356deg; animation-timing-function: cubic-bezier(0.45, 0, 0.55, 1); }
  82% { --ry: 361.5deg; animation-timing-function: cubic-bezier(0.25, 0.6, 0.35, 1); }
  100% { --ry: 360deg; }
}

@keyframes orbling-spin-body {
  0% { scale: 1 1; animation-timing-function: cubic-bezier(0.25, 0.6, 0.35, 1); }
  18% { scale: 1.06 0.94; animation-timing-function: cubic-bezier(0.65, 0, 0.35, 1); }
  37% { scale: 0.94 1.06; animation-timing-function: cubic-bezier(0.65, 0, 0.35, 1); }
  56% { scale: 1.03 0.97; animation-timing-function: cubic-bezier(0.45, 0, 0.55, 1); }
  70% { scale: 0.99 1.01; }
  82%, 100% { scale: 1 1; }
}

.orbling[data-act="dots"] .orbling-eyes {
  animation: orbling-dots-eyes var(--d) var(--ease) infinite both;
}

.orbling[data-act="dots"] .orbling-body {
  animation: orbling-dots-body var(--d) var(--ease) infinite both;
}

.orbling[data-act="dots"] .orbling-tint {
  animation: orbling-dots-tint var(--d) var(--ease) infinite both;
}

.orbling[data-act="dots"] .orbling-dot[data-side="l"] {
  animation: orbling-dot-l var(--d) var(--ease) infinite both;
}

.orbling[data-act="dots"] .orbling-dot[data-side="r"] {
  animation: orbling-dot-r var(--d) var(--ease) infinite both;
}

@keyframes orbling-dots-eyes {
  0%, 6% { opacity: 1; }
  14%, 86% { opacity: 0; }
  95%, 100% { opacity: 1; }
}

@keyframes orbling-dots-tint {
  0%, 8% { opacity: 0; }
  18%, 82% { opacity: 1; }
  92%, 100% { opacity: 0; }
}

@keyframes orbling-dots-body {
  0%, 4% { scale: 1; translate: 0 0; }
  18% { scale: 0.22; }
  33% { translate: 0 0; animation-timing-function: var(--rise); }
  39% { translate: 0 -10%; animation-timing-function: var(--fall); }
  45% { translate: 0 0; }
  57% { translate: 0 0; animation-timing-function: var(--rise); }
  63% { translate: 0 -10%; animation-timing-function: var(--fall); }
  69% { translate: 0 0; }
  82% { scale: 0.22; }
  96%, 100% { scale: 1; translate: 0 0; }
}

@keyframes orbling-dot-l {
  0%, 10% { translate: 0 0; opacity: 0; }
  12% { opacity: 1; }
  24% { translate: -164% 0; }
  27% { translate: -164% 0; animation-timing-function: var(--rise); }
  33% { translate: -164% -45%; animation-timing-function: var(--fall); }
  39% { translate: -164% 0; }
